from datetime import datetime
import sqlite3

import flask

import config
import database


def _open_connection():
    """Give every request its own short-lived SQLite connection, including health checks."""
    settings = flask.current_app.config
    flask.g.connection = database.get_connection(settings['DATABASE'], uri=settings['DATABASE_URI'])


def _close_connection(error=None):
    """Close request resources after success, rejected input or an exception."""
    connection = flask.g.pop('connection', None)
    if connection is not None:
        connection.close()


def _invalid_input(error):
    """Return a domain validation message as JSON with HTTP 400."""
    return flask.jsonify({'error': str(error)}), 400


def _database_unavailable(error):
    """Report a temporary storage failure without disclosing filesystem or SQL details."""
    return flask.jsonify({'error': 'Database unavailable. Start WeekWise and try again.'}), 503


def _http_error(error):
    """Keep framework errors, such as an unknown route or method, in the JSON contract."""
    return flask.jsonify({'error': error.name}), error.code


def _date_range(arguments):
    """Parse strict ISO dates and enforce an increasing, bounded half-open query interval."""
    values = []
    for key in ('from', 'to'):
        text = arguments.get(key, '')
        try:
            value = datetime.strptime(text, config.API_DATE_FORMAT)
        except ValueError as error:
            raise ValueError('Supply from and to dates in YYYY-MM-DD format.') from error
        if value.date().isoformat() != text:
            raise ValueError('Supply from and to dates in YYYY-MM-DD format.')
        values.append(value)
    start, end = values
    if not 0 < (end - start).days <= config.MAX_API_RANGE_DAYS:
        raise ValueError(f'Date range must cover 1–{config.MAX_API_RANGE_DAYS} days.')
    return start, end


def _category_document(connection):
    """Group public bundle rows under their direction names and shared palette colours."""
    directions = {}
    frame = database.get_categories_df(connection)
    for row in frame.reset_index().to_dict('records'):
        key = row['direction_key']
        if key not in directions:
            directions[key] = {'key': key, 'name': row['direction_name'],
                               'colors': config.DIRECTION_COLORS[key], 'bundles': []}
        directions[key]['bundles'].append({'id': row['id'], 'key': row['bundle_key'],
                                           'name': row['bundle_name']})
    return {'directions': list(directions.values())}


def _interaction_body():
    """Accept only the specified JSON fields, leaving transition rules in database.py."""
    body = flask.request.get_json(silent=True)
    required = {'user_id', 'event_id', 'action'}
    if (not isinstance(body, dict) or not required.issubset(body)
            or not set(body).issubset(required | {'rating'})):
        raise ValueError('Supply user_id, event_id, action and an optional rating as JSON.')
    database.validate_interaction_input(body['user_id'], body['event_id'],
                                         body['action'], body.get('rating'))
    return body


def create_app(db_file=config.DB_FILE, uri=False):
    """Create the local API; optional SQLite URI mode supports isolated in-memory tests.

    :param db_file: same SQLite file used by Streamlit, or a test-only shared memory URI
    :param uri: enable SQLite URI interpretation for the supplied database name
    :return: configured Flask application; importing this module starts no server
    """
    application = flask.Flask(__name__)
    application.config.update(DATABASE=db_file, DATABASE_URI=uri)
    application.before_request(_open_connection)
    application.teardown_request(_close_connection)
    application.register_error_handler(ValueError, _invalid_input)
    application.register_error_handler(sqlite3.Error, _database_unavailable)
    for status in (404, 405, 500):
        application.register_error_handler(status, _http_error)

    # Course: L06, A06 – routes map HTTP verbs and URIs to small functions returning JSON.
    @application.get('/health')
    def health():
        """Report the application's protocol version without returning profile data."""
        return flask.jsonify({'status': 'ok', 'version': config.APP_VERSION})

    @application.get('/categories')
    def categories():
        """List directions and their bundles, including both configured colour palettes."""
        return flask.jsonify(_category_document(flask.g.connection))

    @application.get('/events')
    def events():
        """Return public event rows in the requested interval with optional AND filters."""
        start, end = _date_range(flask.request.args)
        rows = database.get_event_records(flask.g.connection, start, end)
        for argument, field in config.API_EVENT_FILTERS.items():
            value = flask.request.args.get(argument)
            if value is not None:
                rows = [row for row in rows if row[field] == value]
        return flask.jsonify(rows)

    @application.get('/events/<int:event_id>')
    def event(event_id):
        """Return one complete occurrence, or HTTP 404 for an unknown ID."""
        row = None
        if 0 < event_id <= config.API_MAX_ID:
            row = database.get_event_row(flask.g.connection, event_id)
        if row is None:
            return flask.jsonify({'error': 'Event was not found.'}), 404
        return flask.jsonify(row)

    @application.post('/interactions')
    def interaction():
        """Delegate one validated action to the shared state machine and return the stored row."""
        body = _interaction_body()
        connection = flask.g.connection
        if not database.user_exists(connection, body['user_id']):
            return flask.jsonify({'error': 'User profile was not found.'}), 404
        if database.get_event_row(connection, body['event_id']) is None:
            return flask.jsonify({'error': 'Event was not found.'}), 404
        result = database.save_interaction(connection, body['user_id'], body['event_id'],
                                            body['action'], body.get('rating'))
        return flask.jsonify(result), 201

    return application


app = create_app()


def prepare_database(db_file=config.DB_FILE, uri=False):
    """Initialize an empty schema when the API is started before Streamlit, preserving all data."""
    connection = database.get_connection(db_file, uri=uri)
    try:
        database.init_db(connection)
    finally:
        connection.close()


if __name__ == '__main__':
    prepare_database()
    app.run(host=config.API_HOST, port=config.API_PORT, debug=False,
            use_reloader=False, threaded=False)
